using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tools ---
var notebook = new Notebook();
var webSearch = new WebSearchTool();

IChatClient client = new ChatClientBuilder(
        new OpenAIClient(openAiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearch.SearchWeb),
    AIFunctionFactory.Create(webSearch.FetchPage),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// --- Prompt ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching \"{topic}\" ...\n");

var systemPrompt = """
    You are a research agent. Your goal is to research the given topic thoroughly
    and produce a concise, well-structured summary.

    Workflow:
    1. Use SearchWeb to find relevant pages about the topic.
    2. Use FetchPage to read promising results.
    3. Use AddNote to record key facts, data points, and quotes as you go.
    4. Use GetNotes to review everything you've collected.
    5. Finally, write a clear summary based on your notes.

    Be methodical: search, read, take notes, then summarize. Include citations
    where possible. Aim for 3-5 search queries to get broad coverage.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic and provide a summary:\n\n{topic}"),
};

var options = new ChatOptions { Tools = tools };

// --- Agent loop ---
var response = await client.GetResponseAsync(messages, options);

Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("  RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine(response.Text);
Console.WriteLine("═══════════════════════════════════════════");

if (notebook.Notes.Count > 0)
{
    Console.WriteLine($"\n📝 {notebook.Notes.Count} note(s) collected during research.\n");
}

