/// <summary>Provides web searching capabilities using DuckDuckGo's HTML interface.</summary>
sealed class WebSearchTool
{
    private readonly HttpClient _http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" }
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for a query and return a list of result titles and URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var html = await _http.GetStringAsync(
                $"https://html.duckduckgo.com/html/?q={encoded}");

            var results = new List<object>();
            // Extract result links from DuckDuckGo HTML results
            var linkMatches = Regex.Matches(html,
                @"<a[^>]+class=""result__a""[^>]+href=""([^""]+)""[^>]*>(.*?)</a>",
                RegexOptions.Singleline);

            foreach (Match match in linkMatches.Take(8))
            {
                var url = WebUtility.HtmlDecode(match.Groups[1].Value);
                var title = Regex.Replace(
                    WebUtility.HtmlDecode(match.Groups[2].Value), "<.*?>", "").Trim();

                // DuckDuckGo wraps URLs in a redirect; extract the actual URL
                if (url.Contains("uddg="))
                {
                    var uddg = Regex.Match(url, @"uddg=([^&]+)");
                    if (uddg.Success) url = WebUtility.UrlDecode(uddg.Groups[1].Value);
                }

                if (!string.IsNullOrEmpty(title))
                    results.Add(new { title, url });
            }

            // Also grab snippets
            var snippetMatches = Regex.Matches(html,
                @"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
                RegexOptions.Singleline);

            for (int i = 0; i < Math.Min(results.Count, snippetMatches.Count); i++)
            {
                var snippet = Regex.Replace(
                    WebUtility.HtmlDecode(snippetMatches[i].Groups[1].Value),
                    "<.*?>", "").Trim();
                results[i] = new
                {
                    ((dynamic)results[i]).title,
                    ((dynamic)results[i]).url,
                    snippet,
                };
            }

            return results.Count > 0
                ? JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true })
                : "No results found.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Fetch and extract the main text content from a web page URL.")]
    public async Task<string> FetchPage(
        [Description("The URL to fetch")] string url)
    {
        try
        {
            var html = await _http.GetStringAsync(url);

            // Strip script/style tags, then all HTML tags, collapse whitespace
            html = Regex.Replace(html, @"<(script|style)[^>]*>.*?</\1>", " ",
                RegexOptions.Singleline | RegexOptions.IgnoreCase);
            html = Regex.Replace(html, @"<[^>]+>", " ");
            html = WebUtility.HtmlDecode(html);
            html = Regex.Replace(html, @"\s+", " ").Trim();

            // Limit to ~6000 chars to stay within context limits
            return html.Length > 6000 ? html[..6000] + "... [truncated]" : html;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }
}

/// <summary>A simple note-taking tool for the agent to record findings.</summary>
sealed class Notebook
{
    public List<string> Notes { get; } = [];

    [Description("Add a research note. Use this to record key facts, quotes, or data points found during research.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        Notes.Add(note);
        return $"Note #{Notes.Count} saved.";
    }

    [Description("Retrieve all notes collected so far.")]
    public string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < Notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {Notes[i]}");
        return sb.ToString();
    }
}

